while (x < 3) {
  hq[x] = new HeapQuiz();
  hq[x].id = x;
  x = x + 1;
}
// hq[0]→obj0, hq[1]→obj1, hq[2]→obj2, hq[3]=null, hq[4]=null
hq[3] = hq[1];   // hq[3]→obj1
hq[4] = hq[1];   // hq[4]→obj1
hq[3] = null;    // hq[3]→null
hq[4] = hq[0];   // hq[4]→obj0
hq[0] = hq[3];   // hq[0]→null（hq[3]是null）
hq[3] = hq[2];   // hq[3]→obj2
hq[2] = hq[0];   // hq[2]→null（hq[0]是null）
// 最终：hq[0]=null, hq[1]→obj1, hq[2]=null, hq[3]→obj2, hq[4]→obj0

